AND chk02_class_tree_id IN (

)
AND ( ( chk03_daily_list_write_id IS NULL
        AND COALESCE(chk01_use_yn,'false') = 'true'
        AND COALESCE(chk02_use_yn,'false') = 'true' )
      OR ( chk03_daily_list_write_id IS NOT NULL ) )
AND ( ( #{unCheckYn} = 'true'  AND chk03_answer_cd IS NULL ) OR ( #{unCheckYn} = 'false' ) )
AND ( ( #{unConfirmYn} = 'true' AND COALESCE(chk03_confirm_yn,'false') = 'false' ) OR ( #{unConfirmYn} = 'false' ) )
AND CONCAT(chk02_class_tree_nm, chk02_content, chk02_explan, f_org_nm(org_id, #{date}), f_emp_kor_nm(person_id)) LIKE #{searchText}
AND COALESCE(chk03_confirmer_id, confirmer_id) = #{confirmerId}

mapper.select:
WITH chkList AS (
) SELECT row_number() OVER() AS key_id, chk02_company_id AS company_id, chk02_daily_list_id AS daily_list_id, chk02_class_tree_id AS class_tree_id, chk02_class_tree_nm AS class_tree_name, chk02_content AS content, chk02_explan AS explan, chk02_cutoff AS cutoff, chk02_window_no AS window_no, chk02_seq AS seq, chk02_use_yn AS use_yn, chk03_daily_list_write_id AS daily_list_write_id, chk03_answer_cd AS answer_code, CASE WHEN chk03_answer_cd IS NOT NULL THEN f_cdnm('AnswerCode', chk03_answer_cd, chk02_company_id, #{date}) ELSE '' END || CASE WHEN chk03_reason IS NOT NULL THEN ' (' || chk03_reason || ')' ELSE '' END AS reason, org_id AS org_id, org_nm AS org_name, person_id AS person_id, person_nm AS person_name, confirmer.emp00_person_id AS confirmer_id, confirmer.emp00_kor_nm AS confirmer_name, COALESCE(chk03_confirm_yn,'false') = 'true' AS confirm_yn FROM chkList
LEFT JOIN getPerson(#{companyId}, #{date}) confirmer ON confirmer.emp00_person_id = COALESCE(chk03_confirmer_id, confirmer_id) WHERE 1=1
ORDER BY chk01_seq, chk02_seq, f_org_nm(org_id, #{date}) COLLATE "ko_KR.utf8" ASC, f_emp_kor_nm(person_id) COLLATE "ko_KR.utf8" ASC LIMIT #{limit} OFFSET #{offset}

WITH chkList AS (
) SELECT count(*) FROM chkList
WHERE 1=1
